<?php
namespace SignalPilot\Services;use SignalPilot\Storage\JsonStorageProvider;use SignalPilot\AI\OpenAIProvider;use SignalPilot\MarketData\SimulatedMarketDataProvider;use SignalPilot\Broker\PaperBroker;
class AppService{public function __construct(public JsonStorageProvider $s){} public function settings():array{$rows=$this->s->all('settings');$out=[];foreach($rows as $r)$out[$r['key']]=$r['value'];return $out;} public function log(string $level,string $msg,array $ctx=[]):void{$this->s->insert('logs',['level'=>$level,'message'=>$msg,'context'=>$ctx]);}
 public function scan():array{$set=$this->settings();$md=new SimulatedMarketDataProvider;$ai=new OpenAIProvider;$out=[];foreach($this->s->all('watchlist') as $w){if(!($w['enabled']??true))continue;$data=$md->indicators($w['symbol']);$decision=$ai->evaluateOpportunity($data,$set,$this->s->all('strategies')[0]??[]);$saved=$this->s->insert('ai_decisions',['symbol'=>$w['symbol'],'market_data'=>$data,'decision'=>$decision]);if(($decision['action']??'')==='BUY'&&($decision['confidence']??0)>=($set['confidence_threshold']??75)){$opp=$this->s->insert('opportunities',['symbol'=>$w['symbol'],'status'=>'pending','current_price'=>$data['price'],'entry'=>$decision['entry'],'stop_loss'=>$decision['stop_loss'],'take_profit'=>$decision['take_profit'],'reward_risk'=>$decision['reward_risk'],'confidence'=>$decision['confidence'],'reason'=>$decision['reason'],'ai_decision_id'=>$saved['id']]);$this->queueEmail('Opportunity Detected',$set['notification_email']??'', $opp);$out[]=$opp;}}$this->s->backup();return $out;}
 public function queueEmail(string $type,string $to,array $payload):void{$this->s->insert('email_queue',['type'=>$type,'to'=>$to,'payload'=>$payload,'status'=>'queued']);$this->s->insert('notifications',['type'=>$type,'channel'=>'email','recipient'=>$to,'payload'=>$payload,'status'=>'queued']);}
 public function approve(string $id):array{$opp=$this->s->find('opportunities',$id);if(!$opp)throw new \RuntimeException('Opportunity not found');$trade=(new PaperBroker($this->s))->openTradeFromOpportunity($opp,$this->settings());$this->s->update('opportunities',$id,['status'=>'approved','approved_at'=>date('c')]);$this->log('info','Trade approved',['opportunity'=>$id,'trade'=>$trade['id']]);return $trade;}
 public function deny(string $id):array{$opp=$this->s->update('opportunities',$id,['status'=>'rejected','rejected_at'=>date('c')]);$this->log('info','Opportunity denied',['opportunity'=>$id]);return $opp;}}
